   "lýsing": "Þáttaröð fyrir alla fjölskylduna byggð á samnefndri metsölubók eftir Gunnar Helgason. Jón fer til Vestmannaeyja með liðsfélögum sínum úr Fálkum til að keppa á stærsta og skemmtilegasta fótboltamóti ársins. Draumar hans hafa þó verið slæmir þar sem eldgos og undarlega vondur markmaður eru að trufla hann. Í raunveruleikanum er það þó Ívar, brjálaði boltaþjófurinn, sem er hans helsti óvinur. Samtímis þarf Rósa að berjast fyrir tilverurétti sínum hjá Fylki. Innan vallar eru þau öll andstæðingar en utan vallar þurfa þau að snúa bökum saman og berjast upp á líf eða dauða.",
