   "lýsing": "Heimildarmynd í tveimur hlutum eftir Ágúst Guðmundsson og Jón Þór Hannesson um ævintýralegan feril Gunnars Þórðarsonar. Þroskasaga tónskálds sem aldrei fór í tónlistarskóla. Mörg vinsælustu lög síðustu áratuga eru frá Gunnari komin: Bláu augun þín, Þú og ég, Gaggó Vest, Vetrarsól, Þitt fyrsta bros og þannig mætti lengi telja. Árið 2005 voru hljóðrituð lög hans orðin 500 og síðan hefur bæst við. Á síðari árum hefur hann samið hljómsveitarverk og kórverk í klassískum stíl, enn fremur óperu sem þykir marka tímamót í íslenskri tónlistarsögu.",
