   "lýsing": "Íslensk heimildarmynd um fjórar ungar stúlkur sem stíga sín fyrstu skref sem leiðsögumenn veiðimanna við Laxá í Aðaldal, stærstu laxveiðiá landsins. Stúlkurnar eru sjöunda kynslóð leiðsögumanna við ána og fjölskyldusaga þeirra samofin árbakkanum. Eftir því sem líður á sumarið eykst sjálfstraust þeirra og færni í faginu en á sama tíma blasa við áskoranir, bæði gagnvart náttúrunni og framtíð fjölskyldufyrirtækisins. Leikstjóri: Gagga Jónsdóttir. Framleiðsla: Sagafilm.",
