   "lýsing": "Listræn heimildarmynd frá 2021 byggð á ævisögu hinnar mexíkósku Ednu Lupitu. Edna mætir innri djöflum sínum með því að sviðsetja atburði úr fortíð sinni með hjálp atvinnuleikara. Með fyrirgefningu og sjálfsást að leiðarljósi dregur hún erfiðar minningar fram í dagsljósið og rannsakar eigin hugarfylgsni, ævilanga baráttu við geðsjúkdóma og sjálfsvígshugsanir. Ekki einleikið býður áhorfendum að fara með Ednu í tilfinningalegt ferðalag þar sem hún uppgötvar mátt leiklistarinnar í leit sinni að andlegum bata. Leikarar: Edna Lupita Mastache Gomez, Sólveig Guðmundsdóttir og Valur Freyr Einarsson. Leikstjórn: Ásthildur Kjartansdóttir og Anna Þóra Steinþórsdóttir. Framleiðsla: Rebella filmworks og Klipp.\n\n\n\nEf þú upplifir vanlíðan og þarft einhvern að tala við, hafðu samband við Hjálparsíma Rauða krossins 1717, netspjall 1717.is eða Píeta samtökin í síma: 552 3318.\n\nFyrir stuðning í sorg hafið samband við Sorgarmiðstöð í síma 551 4141 eða sorgarmidstod@sorgarmidstod.is",
