   "lýsing": "Heimildarmynd um hljómsveitina Purrk Pillnikk sem kom eins og vígahnöttur inn í íslenskan tónlistarheim í upphafi níunda áratugarins. Á átján mánaða ferli lék Pukkur Pillnikk ríflega sextíu lög á tæplega sextíu tónleikum. Nær öll lögin voru gefin út að undanskilinni fimm laga syrpu sem bar heitið Orð fyrir dauða og hljómaði aðeins einu sinni – á síðustu tónleikum hljómsveitarinnar. Þegar sveitin varð fertug kom hún saman á ný og tók upp verkið. Mynd eftir Kolbein Hring Bambus Einarsson og Tómas Sturluson.",
