   "lýsing": "Íslensk heimildarmynd frá 2022 sem gerð var í tilefni þess að 50 ár voru liðin síðan hafist var handa við að tengja raforkukerfi landsmanna umhverfis landið. Rakin er saga byggingar byggðalínu frá 1972-1984. Verkið var unnið af metnaði og framsækni eljusamra einstaklinga við krefjandi og frumstæðar aðstæður. Áður óbirt viðtöl við einstaklinga sem tileinkuðu líf sín byggðalínuævintýrinu, sem og persónulegar myndbandsupptökur frá þessum tíma, glæða söguna lífi.",
