   "imdb_flokkar": null,
   "lýsing": "Íslensk heimildarmynd þar sem við kynnumst átta íslenskum konum á ólíkum aldri sem eiga það sameiginlegt að glíma við sjúkdóminn endómetríósu. Endómetríósa er krónískur bólgu- og verkjasjúkdómur sem hefur áhrif á milljónir kvenna um allan heim. Í myndinni segja konurnar frá líkamlegum, tilfinningalegum og félagslegum áskorunum sem þær standa frammi fyrir vegna þessa flókna og óvægna sjúkdóms. Leikstjórn: Þóra Karítas Árnadóttir. Framleiðsla: Silfra Productions og Endó-samtökin.",
