   "lýsing": "Heimildarmynd frá 2022 um Auði Haraldsdóttur. Auður kom sem stormsveipur inn í íslenskt bókmenntasamfélag með skáldsöguna Hvunndagshetjuna, árið 1979. Hér ræðir Auður Jónsdóttir, rithöfundur og blaðamaður, við Auði Haraldsdóttur um lífið og ferilinn. Álitsgjafar og samferðafólk Auðar ræða verk hennar og farið er yfir samfélagslegt- og bókmenntalegt mikilvægi þeirra. Einnig les Sigrún Edda Björnsdóttir, leikkona, nokkur brot úr bókum Auðar. Handrit og umsjón: Auður Jónsdóttir. Kvikmyndastjórn: Jón Egill Bergþórsson.",
