   "lýsing": "Svipmyndir af Reykjavík sem Loftur Guðmundsson tók á lýðveldisárinu 1944. Farið er aftur í tímann og fylgst með lífi og uppbyggingu í bæ sem er að breytast í borg. Örar breytingar áttu sér stað og hin mikla fólksfjölgun í Reykjavík kallaði á gríðarlegar framkvæmdir. Gatnagerð og nýbyggingar setja sinn svip á myndina, en einnig börn að leik, sótarar, skátar og sundgarpar. Kvikmyndasafn Íslands setti myndina saman úr tökum Lofts og skannaði hana í góðum gæðum. Loftur náði aldrei að frumsýna myndina sjálfur.",
