   "imdb_flokkar": null,
   "lýsing": "Íslenskir heimildarþættir eftir Láru Zulima Ómarsdóttur. Hvernig er að búa í nánum tengslum við náttúruna? Hvað er það í náttúrunni sem kallar svo sterkt á suma? Lára kynnist viðmælendum sínum og fer með þeim á þeirra uppáhaldsstaði, þar á meðal leynistaði sem fáir þekkja. Hún sýnir svo bandaríska ljósmyndaranum og ævintýramanninum Chris Burkard þessar einstöku náttúrugersemar, en hann sérhæfir sig í ljósmyndun á köldum slóðum. Framleiðsla: Zulima ehf.",
