   "lýsing": "Heimildarþættir um þróun íslensks táknmáls frá fyrri tíð til dagsins í dag. Skoðað er hvaða samfélagslegu, menningarlegu og málfræðilegu áhrif móta íslenskt táknmál nútímans, hvað felst í vönduðu íslensku táknmáli og hvernig málið stendur í samanburði við önnur táknmál. Hjördís Anna Haraldsdóttir ræðir við fræðimenn og sérfræðinga í íslensku táknmáli auk notenda málsins í leit að ólíkum sjónarhornum og svörum um stöðu og framtíð málsins.",
