   "lýsing": "Ný íslensk heimildarþáttaröð í umsjón Ara Eldjárns um íslenskar kvikmyndir. Í hverjum þætti er ein sígild kvikmynd tekin fyrir. Skyggnst er á bak við tjöldin og áður óséð myndefni birt. Rætt er við leikstjóra, handritshöfunda, framleiðendur, leikara, búninga- og leikmyndahönnuði, kvikmyndastjóra, klippara og fleira fagfólk, sem ljóstra upp ýmsum leyndarmálum frá gerð myndanna.",
