   "imdb_flokkar": null,
   "lýsing": "Íslensk heimildarmynd  um ferð Guðna Th. Jóhannessonar, þáverandi forseta Íslands, á þungarokkshátíðina Wacken í Þýskalandi árið 2023. Hátíðin er ein sú stærsta og sögufrægasta sinnar tegundar. Íslenskar þungarokksveitir hafa verið aufúsugestir á hátíðinni um árabil og árið 2023 var þar engin undantekning. Fjórar annálaðar sveitir léku á hátíðinni, Skálmöld, Sólstafir, The Vintage Caravan og Krownest. Guðna þótti við hæfi að heiðra sveitirnar með nærveru sinni. Hann var heiðursgestur á hátíðinni og eini þjóðarleiðtoginn á staðnum. Ólafur Páll Gunnarsson fylgdi Guðna og sveitunum á hátíðina. Dagskrárgerð: Ólafur Páll Gunnarsson, Ívar Kristján Ívarsson og Jóhannes Tryggvason.",
   "hlekkur": "https://www.ruv.is/sjonvarp/spila/thungarokksvikingar-a-wacken/35260/ag8fu1",
