   "imdb_flokkar": null,
   "lýsing": "Íslenskir heimildarþættir um náttúruhamfarir á Norðurlöndunum og viðbrögð við þeim. Náttúruhamfarir eru nú þegar orðnar tíðari og ofsafengnari um allan heim vegna loftslagsbreytinga. Hvað má læra af því hvernig tekist er á við skógarelda í Finnlandi, skriðuföll í Noregi, sjávarflóð í Svíþjóð, ofsarigningu í Danmörku og jarðskjálfta, eldgos og snjóflóð á Íslandi? Hvernig drögum við úr skaðanum og aukum seiglu og viðnámsþrótt samfélaga til að takast á við þessar hættur?",
