   "imdb_flokkar": null,
   "lýsing": "Heimildarþáttur um langvinnt covid, sjúkdómsástand sem milljónir einstaklinga víða um heim glíma við í kjölfar COVID-19 sjúkdómsins. Einkennin eru afar einstaklingsbundin, fjölbreytt og geta haft áhrif á mörg líffæri. Í mörgum tilfellum getur langvinnt covid leitt til ME, alvarlegs taugasjúkdóms sem engin lækning hefur enn fundist við. Í þættinum er fjallað um stöðuna hvað varðar læknavísindin, félagslegu úrræðin og reynslu einstaklinga af þessum sjúkdómum. Dagskrárgerð: Páll Kristinn Pálsson.",
