   "lýsing": "Eva María Jónsdóttir og Pétur Blöndal fara í rannsóknarleiðangur og draga fram þræði ljóðsins í íslensku samfélagi. Hafa ljóð þýðingu í tilverunni og geta þau breytt lífi fólks? Þau skoða þætti sem ná yfir allt frá leikskólum til elliheimila, vöggu til grafar, ást til haturs, tónlist til myndlistar, göldrum til vísinda, rímum til rapps og landnámi til þessa dags. Dagskrárgerð: Jakob Halldórsson.",
