   "lýsing": "Íslenskir heimildarþættir um uppgang hatursorðræðu á Íslandi og bakslagið sem orðið hefur í baráttu ýmissa minnihlutahópa á síðustu misserum. Leitast er við að svara spurningunni um hvernig bakslagið fór af stað, hvaðan hatrið stafar og hvaða leið er út úr þessari stöðu. Rætt er við sérfræðinga, stjórnmálafólk og þau sem hafa orðið fyrir barðinu á hatursorðræðu auk þess sem ljósi er varpað á aukið aðgengi ungs fólks að hatri í gegnum samfélagsmiðla. Umsjón: Ingileif Friðriksdóttir. Leikstjórn: Hrafn Jónsson. Framleiðsla: Ketchup Creative.",
