   "lýsing": "Ferðaþættir þar sem leikarinn Örn Árnason bregður sér í hlutverk leiðsögumanns og ferðast um áhugaverða staði við þjóðveginn eða örskammt frá. Frikki Frikk, tökumaður og ljósmyndari, er fylgdarsveinn Arnar í þessum ferðum og saman sýna þeir fram á að stundum er óþarfi að leita langt yfir skammt. Léttir þættir þar sem fjallað er um náttúru, sögu og menningu.",
