   "imdb_hlekkur": null,
   "imdb_flokkar": null,
   "lýsing": "Upptaka frá uppistandssýningu Gísla Einarssonar sem sýnd var á Sögulofti Landnámsseturs Íslands í Borgarnesi. Árið 1772 kom Ferðabók fræðimannanna Eggerts Ólafssonar og Bjarna Pálssonar út í fyrsta sinn en hún byggði á rannsóknum þeirra á landsháttum á Íslandi og lífi Íslendinga. Gísli Einarsson hefur undanfarinn aldarfjórðung ferðast fram og aftur um landið og stúderað landshætti og líf landans með það að markmiði að taka upp þráðinn þar sem Eggert og Bjarni skildu við. Vinnubrögð Gísla eru ófagleg og hvarvetna er kastað til höndum. Útkoman er mislukkað grín þar sem hæðst er á ósmekklegan hátt að einstaka byggðarlögum og íbúum þeirra. Höfundur og flytjandi: Gísli Einarsson.",
