   "lýsing": "Íslenskir heimildarþættir um ferðalag Hringfarans, Kristjáns Gíslasonar, og Ásdísar Rósu, eiginkonu hans. Síðla árs 2023 ferðuðust þau á mótorhjóli um Japan. Ferðalagið reyndi á hjónin á ýmsa vegu og framandi venjur, menning og tungumál gerðu þeim erfitt fyrir. En smám saman lærðu þau á lífstaktinn og nutu ferðalagsins. Þegar upp var staðið reyndist Japan eitt eftirminnilegasta landið sem Hringfarinn hefur heimsótt.",
