   "imdb_hlekkur": null,
   "imdb_flokkar": null,
   "lýsing": "Íslenskir heimildarþættir um ferðalag hjónanna Kristjáns Gíslasonar og Ásdísar Rósu Baldursdóttur, en þau ferðuðust hringinn í kringum Ísland á mótorhjólum sumarið 2020.  Fylgst er með hjónunum upplifa land og þjóð á nýjan hátt þegar þau hjóla 7000 kílómetra á 40 dögum.",
