   "lýsing": "Þáttaröð um mat og matarmenningu Íslendinga allt frá landnámi til dagsins í dag – og jafnvel nokkur skref inn í framtíðina. Gísli og Silla fara með áhorfendur í rannsóknarleiðangur þar sem þau skoða hinar ýmsu mýtur og sturlaðar staðreyndir um mat. Matarsérfræðingar greina matarhefðir, tískur og strauma – allt frá súrmat til skordýrasnakks – og stjörnukokkar fá það verkefni að búa til gómsætar máltíðir úr vinsælu hráefni liðinna tíma. Umsjón: Gísli Einarsson og Sigurlaug Margrét Jónasdóttir. Dagskrárgerð: Konráð Pálmason.",
