   "imdb_flokkar": null,
   "lýsing": "Danskur heimildarþáttur frá 2025 um Söruh, unga konu sem svipti sig lífi eftir baráttu við andleg veikindi. Aðstandendur segja frá því hvernig kerfið brást Söruh sem reyndi ítrekað að leita sér aðstoðar. Þátturinn er ekki við hæfi barna yngri en 14 ára.\n\n\n\nViðvörun: Í þessum þætti er fjallað um sjálfsvíg. Hann getur valdið vanlíðan hjá áhorfendum.\n\n\n\nEf þú ert með sjálfsvígshusanir og þarft einhvern að tala við, hafðu samband við Hjálparsíma Rauða krossins 1717, netspjall 1717.is eða Píeta samtökin í síma: 552 3318.\n\n\n\nFyrir stuðning í sorg hafið samband við Sorgarmiðstöð í síma 551 4141 eða sorgarmidstod@sorgarmidstod.is",
