   "lýsing": "Sænskur heimildarþáttur frá 2025. Fjallað er um skaðlegar útlitskröfur sem ungar stúlkur standa frammi fyrir. Skoðað er hvernig líkami kvenna hefur birst í dægurmenningu síðustu áratugi og hvaða áhrif samfélagsmiðlar hafa á líkamsímynd. Í þættinum er fjallað um átröskun. Hjálparsími Rauða krossins er opinn allan sólarhringinn - símanúmerið er 1717.",
