   "lýsing": "Þáttaröð í sex hlutum þar sem Steiney Skúladóttir og Sigurlaug Sara Gunnarsdóttir kryfja til mergjar geðheilsu og greiningu á andlegri vanheilsu ungs fólks, en kvíði og aðrir andlegir kvillar eru sívaxandi vandamál. Í þáttunum er fjallað um nokkra tiltekna kvilla, meðferð og mögulegar úrlausnir, algengar mýtur og rætt við fólk sem greinst hefur með geðröskun, aðstandendur og fagfólk. Þættirnir eru sjálfstætt framhald Edduverðlaunaþáttaraðarinnar Framapots. Leikstjóri: Arnór Pálmi Arnarsson. Framleitt af Sagafilm.",
