   "lýsing": "Íslensk heimildarmynd um sjálfsvíg á Íslandi og reynslu aðstandenda þeirra sem falla fyrir eigin hendi. Talið er að hátt í 600 sjálfsvígstilraunir sé gerðar árlega á Íslandi og að á milli 30 og 50 manns svipti sig lífi ár hvert. Í myndinni er leitast við að vekja umræðu um efni sem ríkt hefur þöggun um til fjölda ára. Tónlistin í myndinni er eftir Óskarsverðlaunahafann Hildi Guðnadóttur. Leikstjórn: Helgi Felixson og Titti Johnson.",
