   "lýsing": "Íslensk heimildarþáttaröð í fjórum þáttum. Þótt meirihluti landsmanna búi í þéttbýli býr sumt fólk á stöðum þar sem náttúran hefur meiri áhrif á líf þess en gengur og gerist. Í þessari þáttaröð greinir fólk frá ýmsum stöðum á landinu frá ástríðu sinni fyrir því, hvers vegna það kýs að búa utan þéttbýlis og hvað veldur því að það vill hvergi annars staðar búa. Dagskrárgerð: Magnús Atli Magnússon og Lára Ómarsdóttir.",
