   "lýsing": "Íslensk heimildarmynd um eldstöðina Kötlu, en þann 12. október 2018 voru hundrað ár frá því hún gaus síðast. Katla er hættulegasta eldfjall landsins og allt fram til dagsins í dag hafa heimamenn, almannavarnir, lögregla, björgunarsveitir og fleiri gert ráðstafanir um hvernig bregðast skuli við, gjósi Katla. Rætt er við heimamenn og viðbragðsaðila um hættur samfara Kötlugosi og talað við vísindamenn um Kötlu og Kötluvá. Dagskrárgerð: Lára Ómarsdóttir og Einar Rafnsson.",
